(function (){"use strict";var RESTING_LINE = "LINK: STABLE // MAG-LOCK: ENGAGED";var LAST_SCRIPT_KEY = "gama_boot_last_script";var MIN_WIDTH = 901; var DWELL_BASE_MS = 620;var DWELL_PER_CHAR_MS = 38;var DWELL_MAX_MS = 2100;var LEAD_IN_MS = 900;var SETTLE_MS = 1400;function prefersReducedMotion(){return ( typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches );} function readLastScriptId(){try{return window.localStorage.getItem(LAST_SCRIPT_KEY);}catch (e){return null;}}function writeLastScriptId(id){try{window.localStorage.setItem(LAST_SCRIPT_KEY, id);}catch (e){}} function inSeason(season, today){if (!season || !season.from || !season.to) return false;var mmdd = String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");if (season.from <= season.to){return mmdd >= season.from && mmdd <= season.to;}return mmdd >= season.from || mmdd <= season.to;} function chooseScript(scripts, today){var seasonal = scripts.filter(function (s){return inSeason(s.season, today);});var pool = seasonal.length ? seasonal : scripts.filter(function (s){return !s.season;});if (!pool.length) pool = scripts;if (!pool.length) return null;var lastId = readLastScriptId();var fresh = pool.filter(function (s){return s.id !== lastId;});var candidates = fresh.length ? fresh : pool;return candidates[Math.floor(Math.random() * candidates.length)];}function dwellFor(line){return Math.min(DWELL_BASE_MS + line.length * DWELL_PER_CHAR_MS, DWELL_MAX_MS);}function play(statusEl, script){var lines = script.lines;var i = 0;statusEl.classList.add("booting");function step(){if (i >= lines.length){window.setTimeout(function (){statusEl.textContent = RESTING_LINE;statusEl.classList.remove("booting");}, SETTLE_MS);return;}var line = lines[i];statusEl.textContent = line;i += 1;window.setTimeout(step, dwellFor(line));}window.setTimeout(step, LEAD_IN_MS);}function init(){var statusEl = document.querySelector(".terminal-header .system-status");if (!statusEl) return;if (typeof GAMA_BOOT_SCRIPTS === "undefined" || !GAMA_BOOT_SCRIPTS.length) return;if (window.innerWidth < MIN_WIDTH) return;if (prefersReducedMotion()) return;var script = chooseScript(GAMA_BOOT_SCRIPTS, new Date());if (!script) return;writeLastScriptId(script.id);play(statusEl, script);}if (document.readyState === "loading"){document.addEventListener("DOMContentLoaded", init);}else{init();}})();